
// Security Hardening: Anti-Clickjacking & Self-XSS Console Warning
(function() {
  if (typeof window !== "undefined") {
    if (window.top !== window.self) {
      try { window.top.location = window.self.location; } catch(e) {}
    }
    if (typeof console !== "undefined" && console.log) {
      console.log("%cتحذير أمني شديد!", "color: red; font-size: 28px; font-weight: 800;");
      console.log("%cهذه الأداة مخصصة للمطورين فقط. لا تقم بلصق أي كود هنا لحماية بياناتك.", "font-size: 14px; color: #F0B90B; font-weight: bold;");
    }
  }
})();


function escHtml(s) {
  if (!s) return "";
  return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;");
}

// --- Antigravity Client-Side Mock API & Offline Store ---
(function(){
  if (typeof window === "undefined") return;

  const SEED_POSTS = [
    { id: "p_1", name: "أحمد من الإسكندرية", iso: "EGY", at: Date.now() - 3600000 * 2, text: "عشتُ حياة جميلة وبسيطة في الإسكندرية، عملت صياداً وعشت 78 عاماً محاطاً بعائلتي وأحفادي.", story: "عشتُ حياة جميلة في الإسكندرية.", r: 14 },
    { id: "p_2", name: "سارة من الرياض", iso: "SAU", at: Date.now() - 3600000 * 5, text: "درست هندسة الحاسوب، أسست مشروعاً تقنياً ناجحاً، وعشت حتى سن الـ 84 حياة مليئة بالإنجاز.", story: "رحلة من التعلم والنجاح التقني.", r: 23 },
    { id: "p_3", name: "يوسف من فاس", iso: "MAR", at: Date.now() - 3600000 * 12, text: "كرست حياتي لفن العمارة والزخرفة المغربية، تركت أثراً طيباً في قلوب كل من عرفني.", story: "حياة بين الأصالة والجمال المعماري.", r: 9 },
    { id: "p_4", name: "مريم من بغداد", iso: "IRQ", at: Date.now() - 3600000 * 24, text: "معلمة أجيال لـ 40 عاماً في مدارس بغداد، التقاعد كان هادئاً بين كتبي وذكرياتي.", story: "تعليم الأجيال أعظم رسالة.", r: 31 },
    { id: "p_5", name: "عمر من الجزائر", iso: "DZA", at: Date.now() - 3600000 * 48, text: "طبيب عام في وهران، قضيت عمري في معالجة الناس ومساعدتهم، توفيت بسلام في سن 80.", story: "الإنسانية والطب مهنة مقدسة.", r: 18 }
  ];

  const SEED_MEMORIALS = [
    { id: "m_1", name: "زيد بن راشد", born: "1960", died: "2042", iso: "OMN", cv: "بستاني وتاجر نخيل محب للخير", lk: "82", words: "رحمه الله وطيب ثراه، عاش صادقاً ومات كريماً.", r: 42 },
    { id: "m_2", name: "نور الهدى", born: "1975", died: "2058", iso: "JOR", cv: "أستاذة جامعية ومربية أجيال", lk: "83", words: "سيدة ذات أثر لا ينسى، تركت علماً ينتفع به.", r: 29 },
    { id: "m_3", name: "كريم المنصور", born: "1952", died: "2031", iso: "TUN", cv: "كاتب وصحفي", lk: "79", words: "عاش حراً ومات نزيهاً، قلمه كان سيف الحق.", r: 37 }
  ];

  function getLocal(key, defaultVal) {
    try {
      const v = localStorage.getItem(key);
      return v ? JSON.parse(v) : defaultVal;
    } catch(e) { return defaultVal; }
  }

  function setLocal(key, val) {
    try { localStorage.setItem(key, JSON.stringify(val)); } catch(e) {}
  }

  function jsonResponse(data, status) {
    const blob = new Blob([JSON.stringify(data)], { type: "application/json" });
    return new Response(blob, {
      status: status || 200,
      statusText: "OK",
      headers: { "Content-Type": "application/json" }
    });
  }

  // Intercept sendBeacon to silence telemetry errors
  const origBeacon = navigator.sendBeacon;
  navigator.sendBeacon = function(url, data) {
    if (typeof url === "string" && (url.includes("/api/") || url.includes("umami"))) {
      return true;
    }
    return origBeacon ? origBeacon.apply(this, arguments) : true;
  };

  // Intercept window.fetch for /api/* and notes.json
  const origFetch = window.fetch;
  window.fetch = async function(resource, init) {
    const urlStr = typeof resource === "string" ? resource : (resource && resource.url) || "";

    if (urlStr.includes("/api/")) {
      let path = "";
      let urlObj = null;
      try {
        urlObj = new URL(urlStr, window.location.origin);
        path = urlObj.pathname;
      } catch(e) {
        path = urlStr.split("?")[0];
      }

      const method = (init && init.method || "GET").toUpperCase();
      let bodyObj = null;
      if (init && init.body) {
        try {
          bodyObj = typeof init.body === "string" ? JSON.parse(init.body) : init.body;
        } catch(e) { bodyObj = init.body; }
      }

      // 1. Error / Beacon
      if (path === "/api/e") {
        return jsonResponse({ ok: true });
      }

      // 2. Posts (Community Stories)
      if (path === "/api/posts") {
        let posts = getLocal("ar_community_posts", null);
        if (!posts) {
          posts = SEED_POSTS;
          setLocal("ar_community_posts", posts);
        }
        return jsonResponse({ ok: true, posts: posts });
      }

      // 3. Post a Story
      if (path === "/api/post" && method === "POST") {
        let posts = getLocal("ar_community_posts", SEED_POSTS);
        const newPost = {
          id: "p_" + Date.now(),
          name: (bodyObj && bodyObj.name) || "مسافر عربي",
          iso: (bodyObj && bodyObj.iso) || "ARA",
          text: (bodyObj && (bodyObj.text || bodyObj.story || bodyObj.title)) || "حياة جميلة وتجربة ملهمة",
          story: (bodyObj && bodyObj.story) || "",
          at: Date.now(),
          r: 1
        };
        posts.unshift(newPost);
        setLocal("ar_community_posts", posts);
        return jsonResponse({ ok: true, id: newPost.id });
      }

      // 4. React to a Post
      if (path === "/api/react") {
        let posts = getLocal("ar_community_posts", SEED_POSTS);
        const postId = bodyObj && bodyObj.id || (urlObj && urlObj.searchParams.get("id"));
        const p = posts.find(item => item.id === postId);
        if (p) {
          p.r = (p.r || 0) + 1;
          setLocal("ar_community_posts", posts);
        }
        return jsonResponse({ ok: true });
      }

      // 5. Memorials List
      if (path === "/api/memorials") {
        let mems = getLocal("ar_memorials", null);
        if (!mems) {
          mems = SEED_MEMORIALS;
          setLocal("ar_memorials", mems);
        }
        return jsonResponse({ ok: true, list: mems });
      }

      // 6. Single or Random Memorial
      if (path === "/api/memorial") {
        let mems = getLocal("ar_memorials", SEED_MEMORIALS);
        if (method === "POST") {
          const newMem = {
            id: "m_" + Date.now(),
            name: (bodyObj && bodyObj.d && bodyObj.d.name) || (bodyObj && bodyObj.name) || "عاشق الحياة",
            born: (bodyObj && bodyObj.d && bodyObj.d.born) || "2026",
            died: (bodyObj && bodyObj.d && bodyObj.d.died) || "2104",
            iso: (bodyObj && bodyObj.d && bodyObj.d.iso) || "ARA",
            cv: (bodyObj && bodyObj.cv) || "عاش حياة مليئة بالسلام",
            words: (bodyObj && bodyObj.words) || "رحمه الله",
            r: 1
          };
          mems.unshift(newMem);
          setLocal("ar_memorials", mems);
          return jsonResponse({ ok: true, id: newMem.id });
        } else {
          const id = urlObj && urlObj.searchParams.get("id");
          const isRandom = urlObj && urlObj.searchParams.get("random");
          let target = null;
          if (id) {
            target = mems.find(m => m.id === id);
          }
          if (!target && (isRandom || mems.length)) {
            target = mems[Math.floor(Math.random() * mems.length)];
          }
          return jsonResponse({ ok: true, d: target || mems[0] || SEED_MEMORIALS[0] });
        }
      }

      // 7. Memorial Reactions, Styles, Own
      if (path === "/api/memreact" || path === "/api/memstyle" || path === "/api/memnews" || path === "/api/memown" || path === "/api/memremove") {
        return jsonResponse({ ok: true, list: [] });
      }

      // 8. Room / Home APIs
      if (path.startsWith("/api/home")) {
        let room = getLocal("ar_room", { it: {}, bgm: "" });
        if (path === "/api/home/set" && bodyObj) {
          room = Object.assign(room, bodyObj);
          setLocal("ar_room", room);
        }
        return jsonResponse({ ok: true, rm: room, me: { tok: "ar_local", room: room } });
      }

      // 9. Lives, Move, Keep
      if (path === "/api/lives" || path.startsWith("/api/keep") || path.startsWith("/api/move")) {
        return jsonResponse({ ok: true, tok: "ar_local_tok", left: 999, c: "AR999", on: false, list: [] });
      }

      return jsonResponse({ ok: true });
    }

    return origFetch.apply(this, arguments);
  };
})();
