// --- Antigravity Binance Donation & Top 5 Supporters Modals ---
window.copyText = function(text, btn) {
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text);
    } else {
      const ta = document.createElement("textarea");
      ta.value = text;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand("copy");
      document.body.removeChild(ta);
    }
    const orig = btn.innerHTML;
    btn.innerHTML = "✅ تم النسخ بنجاح!";
    btn.style.background = "#10B981";
    btn.style.color = "#FFFFFF";
    setTimeout(() => {
      btn.innerHTML = orig;
      btn.style.background = "";
      btn.style.color = "";
    }, 2200);
  } catch (err) {
    alert("العنوان: " + text);
  }
};

window.toggleQR = function(id) {
  const el = document.getElementById(id);
  if (!el) return;
  el.style.display = (el.style.display === "none" || !el.style.display) ? "block" : "none";
};

window.switchDonateTab = function(tabIdx) {
  for (let i = 0; i < 3; i++) {
    const tabBtn = document.getElementById("dTabBtn_" + i);
    const tabPane = document.getElementById("dTabPane_" + i);
    if (tabBtn && tabPane) {
      if (i === tabIdx) {
        tabBtn.className = "d-tab-btn active";
        tabBtn.style.background = "#F0B90B";
        tabBtn.style.color = "#1E2329";
        tabBtn.style.borderColor = "#F0B90B";
        tabPane.style.display = "block";
      } else {
        tabBtn.className = "d-tab-btn";
        tabBtn.style.background = "var(--d-btn-ghost-bg)";
        tabBtn.style.color = "var(--d-ink)";
        tabBtn.style.borderColor = "var(--d-btn-ghost-border)";
        tabPane.style.display = "none";
      }
    }
  }
};

// Default Top 5 Supporters data
window.getTopSupporters = function() {
  const defaultList = [
    { rank: 1, medal: "🥇", name: "فاعل خير 👑", amount: "100 USDT", note: "الداعم الأكبر لتطوير واستضافة سيرفرات اللعبة", level: "الداعم الماسي الأول" },
    { rank: 2, medal: "🥈", name: "داعم سري 🌟", amount: "50 USDT", note: "مساهمة كريمة لاستمرار النسخة العربية", level: "الداعم البلاتيني" },
    { rank: 3, medal: "🥉", name: "أحمد م. ☕", amount: "30 USDT", note: "عاشق للألعاب ومحب للتطوير المستمر", level: "الداعم الذهبي" },
    { rank: 4, medal: "🎖️", name: "شاغر · تبرع لتظهر هنا ✨", amount: "---", note: "مكان مخصص للمساهمين عبر بايننس", level: "متاح للانضمام", vacant: true },
    { rank: 5, medal: "🎖️", name: "شاغر · تبرع لتظهر هنا ✨", amount: "---", note: "مكان مخصص للمساهمين عبر بايننس", level: "متاح للانضمام", vacant: true }
  ];
  try {
    const saved = localStorage.getItem("ar_top_supporters");
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed) && parsed.length > 0) return parsed;
    }
  } catch(e) {}
  return defaultList;
};

// Update tags on top banner & floating pill
window.refreshSupportersTags = function() {
  try {
    const supporters = window.getTopSupporters();
    const top1 = supporters[0];
    const tagTxt = "#1 " + (top1 ? top1.name.replace("👑","").trim() + " (" + top1.amount + ")" : "فاعل خير");
    const topEl = document.getElementById("topLeaderTag");
    if (topEl) topEl.innerText = tagTxt;
    const floatEl = document.getElementById("floatingLeaderTag");
    if (floatEl) floatEl.innerText = top1 ? "#1 " + top1.name : "#1 فاعل خير 👑";
  } catch(e) {}
};

// Open Top 5 Supporters Modal
window.openTopSupportersModal = function() {
  const supporters = window.getTopSupporters();
  const title = "🏆 لوحة الشرف · أفضل 5 داعمين للعبة";

  let listHtml = "";
  supporters.slice(0, 5).forEach((sup, idx) => {
    const rankClass = "rank-" + (idx + 1);
    const vacantClass = sup.vacant ? "vacant" : "";
    listHtml += `
      <div class="ts-card ${rankClass} ${vacantClass}">
        <div class="ts-right">
          <span class="ts-medal">${sup.medal || "🎖️"}</span>
          <div class="ts-info">
            <span class="ts-name">${escHtml(sup.name)}</span>
            <span class="ts-note">${escHtml(sup.note || "")}</span>
          </div>
        </div>
        <div class="ts-left">
          <span class="ts-amount">${escHtml(sup.amount)}</span>
          <span class="ts-level-tag">${escHtml(sup.level || "")}</span>
        </div>
      </div>
    `;
  });

  const html = `
    <div class="d-box">
      <div class="d-modal-header">
        <img src="../game_icon_circle.png" alt="شعار اللعبة" style="width:68px; height:68px; margin:0 auto 10px; display:block; filter:drop-shadow(0 4px 12px rgba(240,185,11,0.35));">
        <h3 class="d-modal-title">لوحة شرف أفضل 5 داعمين</h3>
        <p class="d-modal-desc">
          تكريماً وتقديراً للمساهمين في دعم استضافة النسخة العربية وسيرفرات لعبة <b>1 من 8 مليار</b> واستمرار تطويرها وإضافة مزايا جديدة.
        </p>
      </div>

      <div class="ts-container">
        ${listHtml}
      </div>

      <!-- CTA Box to join Top 5 -->
      <div class="ts-cta-box">
        <div class="ts-cta-title">✨ هل تريد أن يظهر اسمك في التوب 5؟</div>
        <div class="ts-cta-desc">
          تبرع عبر منصة <b>Binance</b> واذكر اسمك في التحويل أو تواصل معنا، وسيتم تكريمك فوراً وإضافة اسمك في أعلى القائمة!
        </div>
        <button type="button" class="ts-cta-btn" onclick="window.openDonateSheet()">
          💛 تبرع الآن عبر Binance واظهر في القائمة
        </button>
      </div>

      <div style="text-align:center; margin-top:14px; font-size:12.5px; color:var(--d-ink2); font-weight:600;">
        ✨ شكراً لكل من ساهم ويساهم في استمرار ودعم اللعبة!
      </div>
</div>
  `;

  if (typeof openSheet === "function") {
    openSheet(title, html);
  }
};

